(() => {
  const entries = [{"category":"Disiplin","question":"Bilakah guru perlu mengemukakan laporan kes disiplin?","answer":["Guru hendaklah mengemukakan laporan apabila mengesan atau menerima maklumat berkaitan salah laku, pelanggaran peraturan, masalah syakhsiah atau perkara yang menjejaskan ketertiban dan keselamatan pelajar.","Laporan hendaklah berdasarkan fakta, pemerhatian dan maklumat yang boleh disahkan."]},{"category":"Hafazan","question":"Bilakah guru perlu menghantar laporan kemajuan hafazan Al-Quran?","answer":["Guru hendaklah mengemukakan laporan apabila mendapati prestasi hafazan Al-Quran seseorang pelajar mengalami kemerosotan dan memerlukan perhatian atau tindakan susulan.","Laporan ini bertujuan membantu pihak Institut mengenal pasti pelajar yang memerlukan pemantauan dan bimbingan khusus."]},{"category":"Akademik","question":"Bilakah guru perlu menghantar laporan kemajuan akademik?","answer":["Guru hendaklah mengemukakan laporan apabila mendapati seseorang pelajar mengalami kemerosotan prestasi akademik atau menunjukkan masalah berkaitan tanggungjawab pembelajaran.","Ini termasuk kegagalan menyiapkan kerja rumah, tugasan sekolah atau melaksanakan arahan pembelajaran yang diberikan."]},{"category":"Aktiviti","question":"Siapakah yang perlu mengisi Borang Laporan Aktiviti Pelajar?","answer":["Borang Laporan Aktiviti Pelajar ditujukan kepada Ketua Bahagian (HOD) atau penganjur aktiviti yang bertanggungjawab menyediakan laporan pelaksanaan aktiviti.","Laporan hendaklah dikemukakan mengikut arahan dan ketetapan pentadbiran Institut."]},{"category":"Umum","question":"Apakah yang berlaku selepas laporan mengenai pelajar dihantar?","answer":["Setiap laporan berkaitan disiplin, hafazan Al-Quran dan akademik akan dihadapkan kepada Timbalan Pengetua Hal Ehwal Pelajar untuk perhatian, pertimbangan dan tindakan yang bersesuaian.","Semakan serta pengesahan maklumat boleh dilaksanakan oleh unit atau pegawai yang bertanggungjawab sebelum keputusan tindakan dimuktamadkan."]},{"category":"Umum","question":"Apakah Teacher's Hub?","answer":["Teacher's Hub ialah portal digital yang menghimpunkan perkhidmatan dan sumber berkaitan pelaporan, pemantauan perkembangan pelajar serta pengurusan aktiviti Institut Tahfiz Al-Quran Sultan Haji Hassanal Bolkiah (ITQSHHB).","Portal ini memudahkan warga pendidik mengakses perkhidmatan yang diperlukan melalui satu platform."]},{"category":"Umum","question":"Siapakah yang boleh menggunakan Teacher's Hub?","answer":["Teacher's Hub disediakan untuk kegunaan warga pendidik ITQSHHB. Akses kepada borang dan sistem tertentu adalah tertakluk kepada kebenaran yang ditetapkan bagi setiap perkhidmatan."]},{"category":"Umum","question":"Adakah saya perlu log masuk untuk menggunakan Teacher's Hub?","answer":["Laman utama Teacher's Hub boleh diakses melalui pelayar web tanpa log masuk khusus. Walau bagaimanapun, sesetengah borang atau sistem yang dipautkan mungkin memerlukan log masuk menggunakan akaun Google yang dibenarkan."]},{"category":"Disiplin","question":"Siapakah yang mengendalikan laporan kes disiplin?","answer":["Laporan kes disiplin akan dikendalikan oleh Unit Syakhsiah dan Disiplin, Bahagian Pembangunan Pelajar. Unit ini bertanggungjawab meneliti laporan dan menyelaraskan tindakan yang bersesuaian.","Sekiranya diperlukan, kes boleh dirujuk kepada Bahagian Kaunseling bagi tujuan bimbingan, intervensi dan tindakan susulan."]},{"category":"Disiplin","question":"Adakah setiap laporan disiplin akan menyebabkan pemotongan markah Jannah?","answer":["Tidak semestinya. Pemotongan markah Jannah bergantung kepada jenis dan tahap kesalahan, bukti yang telah disahkan serta peraturan yang berkuat kuasa.","Penghantaran laporan bukanlah suatu keputusan tatatertib muktamad."]},{"category":"Disiplin","question":"Apakah yang perlu dilakukan jika kes melibatkan keselamatan pelajar?","answer":["Sekiranya kejadian melibatkan ancaman keselamatan, kecederaan atau keadaan yang memerlukan tindakan segera, guru hendaklah mengutamakan keselamatan individu terlibat dan segera memaklumkan kepada pihak bertanggungjawab.","Borang laporan dalam talian tidak menggantikan keperluan tindakan segera dalam situasi kecemasan."]},{"category":"Hafazan","question":"Apakah tindakan terhadap pelajar yang mengalami kemerosotan hafazan?","answer":["Pelajar yang disahkan mengalami kemerosotan hafazan boleh dikenakan sekatan penyertaan dalam aktiviti dalaman dan luaran Institut, tertakluk kepada keputusan pihak Hal Ehwal Pelajar.","Langkah ini bertujuan memberikan keutamaan kepada pemulihan hafazan dan peningkatan prestasi pelajar. Penyertaan semula dalam aktiviti adalah tertakluk kepada penilaian dan keputusan pihak berkenaan."]},{"category":"Akademik","question":"Bolehkah guru melaporkan pelajar yang tidak menyiapkan kerja rumah atau tugasan sekolah?","answer":["Ya. Guru boleh mengemukakan laporan akademik bagi mendapatkan perhatian dan pertimbangan tindakan terhadap pelajar yang gagal menyiapkan tugasan.","Guru digalakkan memberikan maklumat berkaitan tugasan, kekerapan kesalahan serta teguran atau bimbingan yang telah diberikan."]},{"category":"Akademik","question":"Adakah laporan akademik boleh menyebabkan pemotongan markah Jannah?","answer":["Ya. Laporan akademik berpotensi membawa kepada pemotongan markah Jannah sekiranya perbuatan yang dilaporkan memenuhi kategori kesalahan yang diperuntukkan dalam peraturan yang berkuat kuasa.","Walau bagaimanapun, markah tidak akan dipotong secara automatik hanya kerana laporan dikemukakan. Sebarang keputusan hendaklah berdasarkan penelitian, pengesahan dan pertimbangan pihak yang diberi kuasa."]},{"category":"Akademik","question":"Bolehkah pelajar yang mengalami masalah akademik menyertai aktiviti Institut?","answer":["Pelajar yang disahkan mengalami masalah akademik boleh dikenakan sekatan penyertaan dalam aktiviti dalaman atau luaran Institut, tertakluk kepada keputusan pihak Hal Ehwal Pelajar.","Langkah ini bertujuan memastikan pelajar memberikan perhatian terhadap tanggungjawab akademik dan usaha memperbaiki prestasi pembelajaran."]},{"category":"Aktiviti","question":"Apakah kegunaan Kalendar Aktiviti?","answer":["Kalendar Aktiviti membolehkan warga pendidik menyemak jadual aktiviti Institut bagi membantu perancangan dan penyelarasan program.","Sebarang permohonan tempahan atau perubahan tarikh adalah tertakluk kepada prosedur serta kelulusan pihak berkenaan."]},{"category":"Umum","question":"Siapakah yang menentukan tindakan akhir terhadap pelajar?","answer":["Timbalan Pengetua Hal Ehwal Pelajar akan meneliti laporan dan menyelaraskan tindakan yang bersesuaian mengikut bidang kuasa dan peraturan Institut.","Tindakan boleh merangkumi bimbingan, pemantauan, rujukan kaunseling, sekatan penyertaan aktiviti atau tindakan tatatertib yang dibenarkan."]},{"category":"Umum","question":"Adakah laporan guru dianggap sebagai keputusan muktamad?","answer":["Tidak. Laporan guru merupakan maklumat awal untuk penelitian dan tindakan pihak yang bertanggungjawab.","Sebarang tindakan hendaklah berdasarkan fakta dan maklumat yang telah disahkan serta memberikan ruang penjelasan kepada pelajar apabila diperlukan."]},{"category":"Bantuan","question":"Adakah maklumat pelajar yang dilaporkan bersifat sulit?","answer":["Ya. Maklumat berkaitan disiplin, hafazan dan pencapaian akademik pelajar hendaklah dikendalikan secara sulit serta digunakan untuk tujuan rasmi yang dibenarkan sahaja.","Guru hendaklah mengelakkan penyebaran maklumat peribadi pelajar kepada pihak yang tidak berkaitan."]},{"category":"Bantuan","question":"Apakah yang perlu dilakukan jika tersalah menghantar laporan atau pautan tidak berfungsi?","answer":["Sekiranya berlaku kesilapan penghantaran laporan, guru hendaklah memaklumkan kepada pegawai atau penyelaras yang bertanggungjawab terhadap borang berkenaan.","Jika terdapat masalah pautan atau akses, guru boleh menyemak sambungan internet dan kebenaran akaun terlebih dahulu sebelum memaklumkan masalah tersebut kepada pentadbir portal melalui saluran rasmi Institut."]}];
  const list = document.getElementById("faq-list");
  const search = document.getElementById("faq-search");
  const count = document.getElementById("faq-count");
  const empty = document.getElementById("faq-empty");
  const categoryButtons = [...document.querySelectorAll("[data-faq-category]")];
  const openAll = document.getElementById("faq-open-all");
  const closeAll = document.getElementById("faq-close-all");
  const dialog = document.getElementById("faq-dialog");
  const openDialogButton = document.getElementById("faq-open-dialog");
  const closeDialogButton = document.getElementById("faq-close-dialog");
  const featured = document.getElementById("faq-featured");
  let activeCategory = "Semua";

  function setExpanded(item, expanded) {
    const button = item.querySelector(".faq-question");
    const panel = item.querySelector(".faq-answer");
    button.setAttribute("aria-expanded", String(expanded));
    panel.classList.toggle("is-open", expanded);
    panel.setAttribute("aria-hidden", String(!expanded));
    panel.inert = !expanded;
  }

  function render() {
    const query = search.value.trim().toLocaleLowerCase();
    let shown = 0;
    list.querySelectorAll(".faq-item").forEach((item) => {
      const entry = entries[Number(item.dataset.index)];
      const matchesCategory = activeCategory === "Semua" || entry.category === activeCategory;
      const haystack = (entry.question + " " + entry.answer.join(" ")).toLocaleLowerCase();
      const matchesSearch = !query || haystack.includes(query);
      const visible = matchesCategory && matchesSearch;
      item.hidden = !visible;
      if (visible) shown += 1;
      else setExpanded(item, false);
    });
    count.textContent = "Memaparkan " + shown + " daripada " + entries.length + " soalan";
    empty.hidden = shown !== 0;
    openAll.disabled = closeAll.disabled = shown === 0;
  }

  function selectCategory(category) {
    activeCategory = category;
    categoryButtons.forEach((chip) => {
      const active = chip.dataset.faqCategory === category;
      chip.classList.toggle("is-active", active);
      chip.setAttribute("aria-pressed", String(active));
    });
  }

  function openDialog(index) {
    if (typeof index === "number") {
      selectCategory("Semua");
      search.value = entries[index].question;
    } else {
      selectCategory("Semua");
      search.value = "";
    }
    render();
    dialog.showModal();
    document.body.classList.add("faq-dialog-open");
    if (typeof index === "number") {
      const item = list.querySelector(`[data-index="${index}"]`);
      if (item) {
        setExpanded(item, true);
        item.querySelector(".faq-question").focus();
      }
    } else search.focus();
  }

  entries.forEach((entry, index) => {
    const item = document.createElement("article");
    item.className = "faq-item";
    item.dataset.index = String(index);
    item.dataset.category = entry.category;

    const button = document.createElement("button");
    button.className = "faq-question";
    button.type = "button";
    button.id = "faq-question-" + (index + 1);
    button.setAttribute("aria-expanded", "false");
    button.setAttribute("aria-controls", "faq-answer-" + (index + 1));
    const questionText = document.createElement("span");
    questionText.className = "faq-question-text";
    questionText.textContent = entry.question;
    const icon = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    icon.setAttribute("viewBox", "0 0 24 24");
    icon.setAttribute("aria-hidden", "true");
    icon.setAttribute("focusable", "false");
    const vertical = document.createElementNS("http://www.w3.org/2000/svg", "path");
    vertical.setAttribute("class", "faq-icon-vertical");
    vertical.setAttribute("d", "M12 5v14");
    const horizontal = document.createElementNS("http://www.w3.org/2000/svg", "path");
    horizontal.setAttribute("d", "M5 12h14");
    icon.append(vertical, horizontal);
    button.append(questionText, icon);

    const panel = document.createElement("div");
    panel.className = "faq-answer";
    panel.id = "faq-answer-" + (index + 1);
    panel.setAttribute("role", "region");
    panel.setAttribute("aria-labelledby", button.id);
    panel.setAttribute("aria-hidden", "true");
    panel.inert = true;
    const inner = document.createElement("div");
    inner.className = "faq-answer-inner";
    entry.answer.forEach((text) => {
      const paragraph = document.createElement("p");
      paragraph.textContent = text;
      inner.append(paragraph);
    });
    panel.append(inner);
    item.append(button, panel);
    button.addEventListener("click", () => setExpanded(item, button.getAttribute("aria-expanded") !== "true"));
    list.append(item);
  });

  [5, 4, 19].forEach((index) => {
    const entry = entries[index];
    const button = document.createElement("button");
    button.className = "faq-featured-button";
    button.type = "button";
    button.innerHTML = `<span>${entry.category}</span><strong></strong><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m7 4 6 6-6 6"/></svg>`;
    button.querySelector("strong").textContent = entry.question;
    button.addEventListener("click", () => openDialog(index));
    featured.append(button);
  });

  categoryButtons.forEach((button) => button.addEventListener("click", () => {
    selectCategory(button.dataset.faqCategory);
    render();
  }));
  search.addEventListener("input", render);
  openAll.addEventListener("click", () => list.querySelectorAll(".faq-item:not([hidden])").forEach((item) => setExpanded(item, true)));
  closeAll.addEventListener("click", () => list.querySelectorAll(".faq-item:not([hidden])").forEach((item) => setExpanded(item, false)));
  openDialogButton.addEventListener("click", () => openDialog());
  closeDialogButton.addEventListener("click", () => dialog.close());
  dialog.addEventListener("click", (event) => {
    if (event.target === dialog) dialog.close();
  });
  dialog.addEventListener("close", () => {
    document.body.classList.remove("faq-dialog-open");
    openDialogButton.focus();
  });
  render();
})();

